effect.shader:
vec4 s(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
float w(float x, float sigma){ return exp(-(x*x)/(2.0*sigma*sigma)); }
void main(){
vec2 uv = acScreenNorm;
vec2 texel = 1.0/inputImg.size;
float r = radius;
if(r<=0.0){ gl_FragColor = s(uv); return; }
int taps = int(r * (quality==0?2.0:(quality==1?3.0:4.0)));
float sigma = max(0.0001, r*0.6);
vec4 acc = vec4(0.0);
float wsum = 0.0;
for(int i=-1024;i<=1024;i++){
if(i<-taps) continue; if(i>taps) break;
float wi = w(float(i), sigma);
acc += s(uv + vec2(float(i)*texel.x, 0.0)) * wi;
wsum += wi;
}
gl_FragColor = acc/max(0.0001,wsum);
}
